    ('mke1_salario_curto', 'if (cap as f64 * read_f64(rdata::F64_1_2)) < wanted_wage { // mke1: the wage within 1.2 × the cap', 'if (cap as f64 * read_f64(rdata::F64_1_2) * 0.5) < wanted_wage { // mutation: 0.6 × the cap', 'mke_1 wage too high'),
    ('mke2_valor_dias_pares', "if (read_i16(date) as i32) % 2 == 0 { // mke2: the AI's players are valued on odd days", 'if (read_i16(date) as i32) % 2 != 0 { // mutation: valued on even days', 'mke_2 renewal at the end'),
    ('mke2_bosman_sem_marca', '            c.set_leaving_on_bosman(1);\n            c.set_transfer_status(c.transfer_status() & 0xf7);\n            contract_day_shortlist(p);', '            c.set_leaving_on_bosman(0); // mutation: not marked as leaving\n            c.set_transfer_status(c.transfer_status() & 0xf7);\n            contract_day_shortlist(p);', 'mke_2 leaves on a Bosman'),
    ('mke2_renovacao_sem_premio', 'let f = if contract_day_on_list(club, p) { 1.4 } else { 1.0 }; // mke2: the late renewal of a key player', 'let f = if contract_day_on_list(club, p) { 1.0 } else { 1.0 }; // mutation: no premium', 'mke_2 renewal at the end'),
    ('mke3_multa_rebaixamento', 'ftol(v as f64 * read_f64(rdata::F64_0_85)) // mke3: the relegation fee × 0.85', 'ftol(v as f64 * read_f64(rdata::F64_0_5)) // mutation: the relegation fee × 0.5', 'mke_3 relegation clause'),
    ('mke3_inicio_quatro_anos', 'write_u16(sy, read_u16(G_CURRENT_DATE + 2).wrapping_sub(3)); // mke3: the database start goes back 3 years', 'write_u16(sy, read_u16(G_CURRENT_DATE + 2).wrapping_sub(4)); // mutation: 4 years', 'mke_3 relegation clause'),
    ('mke4_inquieto', 'let mut add = ftol((read_f64(F64_1_5) - fl as f64 * read_f64(rdata::F64_0_1)) * u as f64) as u8; // mke4: the unsettlement after a move', 'let mut add = ftol((read_f64(F64_1_5) + 1.0 - fl as f64 * read_f64(rdata::F64_0_1)) * u as f64) as u8; // mutation: 2.5', 'mke_4 moved'),
    ('mke4_piso_da_lista', 'let z = ftol((q as f64 + r as f64 * read_f64(F64_2_9)) * read_f64(F64_1_150)); // mke4: the shortlist rating lifts the floor', 'let z = ftol((q as f64 + r as f64 * read_f64(F64_2_9) * 4.0) * read_f64(F64_1_150)); // mutation: 4 x the rating', 'mke_4 moved'),
